            var section = document.getElementById('tianji-thoughts-section');
            if (!list || !section) return;

            var rows = list.querySelectorAll('.npc-row');
            var visibleCount = 0;

            for (var i = 0; i < rows.length; i++) {
                var name = (rows[i].getAttribute('data-name') || '').trim();
                if (!name) {
                    rows[i].style.display = 'none';
                } else {
                    visibleCount++;
                }
            }

